from typing import List, Optional

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def numComponents(self, head: Optional[ListNode], nums: List[int]) -> int:
        num_set = set(nums)
        cur = head
        ans = 0
        while cur:
            if cur.val in num_set and (cur.next is None or cur.next.val not in num_set):
                ans += 1
            cur = cur.next
        return ans

class Solution {
public:
    int numComponents(ListNode* head, vector<int>& nums) {
        unordered_set<int> num_set(nums.begin(), nums.end());
        ListNode* cur = head;
        int ans = 0;
        while (cur) {
            if (num_set.count(cur->val) && (!cur->next || !num_set.count(cur->next->val))) {
                ans++;
            }
            cur = cur->next;
        }
        return ans;
    }
};

class Solution {
    public int numComponents(ListNode head, int[] nums) {
        Set<Integer> numSet = new HashSet<>();
        for (int x : nums) numSet.add(x);
        ListNode cur = head;
        int ans = 0;
        while (cur != null) {
            if (numSet.contains(cur.val) && (cur.next == null || !numSet.contains(cur.next.val))) {
                ans++;
            }
            cur = cur.next;
        }
        return ans;
    }
}

var numComponents = function(head, nums) {
    const numSet = new Set(nums);
    let cur = head;
    let ans = 0;
    while (cur !== null) {
        if (numSet.has(cur.val) && (cur.next === null || !numSet.has(cur.next.val))) {
            ans++;
        }
        cur = cur.next;
    }
    return ans;
};
